definition.raw:
\label{hstrdef}
\begin{enumerate}
\item  An \emph{$e$-dimensional HS-derivation on $R$ over $k$}  is a $k$-algebra homomorphism
$$\mathbb{D}:R\to R\llbracket \mathbf{X}\rrbracket$$
which is a section of the projection map
$$R\llbracket \mathbf{X}\rrbracket\to R,\ \ \ H\mapsto H(\mathbf{0}).$$

\item An \emph{$m$-truncated $e$-dimensional HS-derivation on $R$ over $k$}  is a $k$-algebra homomorphism
$$\mathbb{D}:R\to R[\mathbf{v}_m]$$
which is a section of the projection map $R[\mathbf{v}_m]\to R$.
\end{enumerate}

\label{firstdefstrict}
If $\mathbb{D}$ is an ($m$-truncated) $e$-dimensional HS-derivation on $R$ over $k$, then we define the following.
\begin{enumerate}
\item The \emph{ring of constants} of $(R,\mathbb{D})$ is
$$\ker(D_{(1,0,\ldots,0)})\cap \ldots \cap \ker(D_{(0,\ldots,0,1)}).$$
Clearly, $R^p$ is contained in the ring of constants of $(R,\mathbb{D})$.

\item We call $(R,\mathbb{D})$ \emph{strict}, if the ring of constants of $\mathbb{D}$ coincides with $R^p$.

\item The \emph{ring of absolute constants} of $(R,\mathbb{D})$ is
$$\bigcap_{\mathbf{i}\neq \mathbf{0}}\ker(D_{\mathbf{i}}).$$
\end{enumerate}

\begin{enumerate}
\item A \emph{$\mathfrak{g}$-derivation on $V$} is a $k$-group scheme action of $\mathfrak{g}$ on $V$ (see Section 12 in \cite{MuAbel}).

\item A \emph{$\mathfrak{g}$-derivation on $R$} is a $\mathfrak{g}$-derivation on $\spec(R)$.

\item We naturally get the notions of a \emph{$\mathfrak{g}$-ring}, a \emph{$\mathfrak{g}$-field} and a \emph{$\mathfrak{g}$-extension}.
\end{enumerate}

We define the following.
\begin{enumerate}
\item An \emph{$F$-derivation} on $V$ is a direct system of $F[m]$-derivations on $V$.

\item A \emph{$G$-derivation} is a $\widehat{G}$-derivation (see Section \ref{gpschemetrun} for the definition of $\widehat{G}$).

\item Similarly we get the notions of an $F$-derivation and a $G$-derivation on $R$.
\end{enumerate}

\label{defpbasis}
Let $\mathbb{D}$ be a $G[m]$-derivation on $K$.

A subset $B\subseteq K$ is called a \emph{canonical $G$-tuple}, if $|B|=e$ and there is a $G[m]$-embedding $(k(G),\mathbb{D}[m]^G)\to \mathbf{K}$ such that $B$ is the image of the set of canonical parameters of $G$, where $\mathbb{D}[m]^G$ is the canonical $G[m]$-derivation from Example \ref{cangex}.

theorem.raw:
\label{quotient}
We have the following.
\begin{enumerate}
\item The quotient scheme $V/\mathfrak{g}$ exists.

\item If $V=\spec(R)$, then $V/\mathfrak{g}=\spec(C_{\mathbb{D}})$, where $C_{\mathbb{D}}$ is the ring of absolute constants of $\mathbf{R}$ (see Definition \ref{firstdefstrict}(3)).
\end{enumerate}

\label{qegdcf}
We have the following.
\begin{enumerate}
\item The theory $\mathfrak{g}-\dcf_{\lambda}$ has quantifier elimination in the language $L^{\lambda}_{e,m}$.

\item Each model of $\mathfrak{g}-\ddf$ embeds into a model of $\mathfrak{g}-\dcf$.

\item The theory $\mathfrak{g}-\dcf$ is a model companion of the theory $\mathfrak{g}-\ddf$.

\item The theory $\mathfrak{g}-\dcf_{\lambda}$ is a model completion of the theory $\mathfrak{g}-\ddf_{\lambda}$.
\end{enumerate}

\label{chain}
The theories $F[m]-\dcf$ form an increasing chain and we have
$$F-\dcf = \bigcup_{m=1}^{\infty}F[m]-\dcf.$$

\label{ggeo}
The $\mathfrak{g}$-field $(K,\mathbb{D})$ is an existentially
closed $\mathfrak{g}$-field if and only if $(K,\mathbb{D})$ satisfies the geometric axioms above.

\label{fgeo}
The $F$-field $\mathbf{K}$ is an existentially
closed $F$-field if and only if $\mathbf{K}$ is a model of the geometric axioms for $\mathfrak{g}-\dcf$.

lemma.raw:
\label{newton}
Let $c_{\mathbf{i},\mathbf{j}}^{\mathbf{k}}$ be as in Remark \ref{gderint2}. For a tuple of natural numbers $\mathbf{n}=(n_1,\ldots,n_e)$, the sum $n_1+\ldots+n_e$ is denoted by $|\mathbf{n}|$. Then we have the following.
\begin{enumerate}
\item If $|\mathbf{k}|>|\mathbf{i}|+|\mathbf{j}|$, then $c_{\mathbf{i},\mathbf{j}}^{\mathbf{k}}=0$.

\item If $|\mathbf{k}|=|\mathbf{i}|+|\mathbf{j}|$ and $\mathbf{k}\neq \mathbf{i}+\mathbf{j}$, then $c_{\mathbf{i},\mathbf{j}}^{\mathbf{k}}=0$.

\item If $\mathbf{k}=\mathbf{i}+\mathbf{j}$, then
$$c_{\mathbf{i},\mathbf{j}}^{\mathbf{k}}={i_1+j_1 \choose i_1}\cdot \ldots \cdot {i_e+j_e \choose i_e}.$$
\end{enumerate}

\label{constantdisjoint}
Let $\mathbf{K}\subseteq \mathbf{L}$ be an extension of $\mathfrak{g}$-fields. Let $C_K$ (resp. $C_L$) be the constant field of $\mathbf{K}$ (resp. $\mathbf{L}$). Then we have the following.
\begin{enumerate}
\item The field $K$ is linearly disjoint from $C_L$ over $C_K$.

\item If $\mathbf{K}$ is strict (see Def. \ref{firstdefstrict}(2)), then the extension $K\subseteq L$ is separable.

\item If the extension $K\subseteq L$ is \'{e}tale and $K$ has a finite degree of imperfection, then $\mathbf{K}$ is strict if and only if $\mathbf{L}$ is strict.
\end{enumerate}

\label{deronc}
Let $\mathbb{D}$ be a $\mathfrak{g}$-derivation on $R$ and $C$ be the ring of constants of $(R,\mathbb{D})$. Then we have the following.
\begin{enumerate}
\item $C$ is a $\mathfrak{g}$-subring.

\item A $\mathfrak{g}$-action on $\spec(C)$ naturally induces a $\mathfrak{g}[m-1]^{\fr}$-action on $\spec(C)$, hence $C$ is naturally a $\mathfrak{g}[m-1]^{\fr}$-ring.
\end{enumerate}

\label{lamb}
Each field of characteristic $p$ has a natural $L^{\lambda}$-structure and we have the following.
\begin{enumerate}
\item A field extension $K\subseteq L$ is an $L^{\lambda}$-extension if and only if $L^p\cap K=K^p$.

\item If $\mathbf{K}\subseteq \mathbf{L}$ is an $L_{e,m}$-extension and $\mathbf{K}$ is strict, then $\mathbf{K}\subseteq \mathbf{L}$ is an $L^{\lambda}_{e,m}$-extension.

\item Suppose $R$ is a subring of a field $L$, $K$ is the field of fractions of $R$ and $R\subseteq L$ is an $L^{\lambda}$-extension. Then $K\subseteq L$ is an $L^{\lambda}$-extension.
\end{enumerate}

\label{elementaryetale}
Let us assume that $\mathbf{K}$ and $\mathbf{L}$ are $\mathfrak{g}$-fields such that $K$ and $L$ are separably closed and that $K$ has finite imperfectness degree. Then the following are equivalent.
\begin{enumerate}
\item The fields $K$ and $L$ have the same (absolute) $p$-basis.

\item The $K$-algebra $L$ is \'{e}tale.

\item The extension $K\subseteq L$ is elementary (in the language of rings).

\item The extension $\mathbf{K}\subseteq \mathbf{L}$ is $L^{\lambda}_{e,m}$-elementary.

\item The extension $\mathbf{K}\subseteq \mathbf{L}$ is $L_{e,m}$-elementary.
\end{enumerate}

\label{nablaL}
Let $V$ be a $K$-scheme and suppose that $(K,\mathbb{D})\subseteq(L,\mathbb{D}')$ is an extension of $m$-truncated $e$-dimensional HS-fields. Then for any $a\in V(L)$, we have
 $\mathbb{D}'_V(a)\in\nabla V(L)$.

\label{gitnabla}
For any $K$-scheme $V$ we have the following:
$$\mathbb{D}_{\nabla(V)}\circ \mathbb{D}_V=c_V\circ \mathbb{D}_V.$$

\label{cVW}
The following are equivalent.
\begin{enumerate}
\item  There is a $\mathfrak{g}$-field extension $(K,\mathbb{D})\subseteq(K(b),\mathbb{D}')$ such that $\mathbb{D}'_V(b_0)=b$.

\item  There is a $\mathfrak{g}$-field extension $(K,\mathbb{D})\subseteq(L,\mathbb{D}')$ such that $\mathbb{D}'_V(b_0)=b$.

\item $c_{n}(W)\subseteq \nabla(W)$.
\end{enumerate}

corollary.raw:
\label{dimconstants}
Let $\mathbf{K}$ be a $\mathfrak{g}$-field and $C$ its field of constants. Then we have
$$[K:C]\leqslant p^e.$$

proof.raw:
The proof goes almost exactly as in \cite[theorem 27.2]{mat}, so we will just sketch the main inductive step which makes clear how the \'{e}tale assumption is used. We apply the induction on the truncation degree. Assume that for $l\in {\mathds{N}}$ (resp. $l<m$) we have extended $\mathbb{D}[l]$ to an $l$-truncated $e$-dimensional HS-derivation $\mathbb{D}':=(D'_{\mathbf{i}})_{\mathbf{i}<[p^l]^e}$ on $S$. Consider the following diagram
\begin{equation*}
 \xymatrixcolsep{2.5pc}\xymatrixrowsep{1.5pc}\xymatrix{& S[\mathbf{X}]/(X_1^{p^l},\ldots,X_e^{p^l}) &
\\ S  \ar[ur]^-{\mathbb{D}'} \ar@{-->}[rr]
 &  & S[\mathbf{X}]/(X_1^{p^{l+1}},\ldots,X_e^{p^{l+1}})  \ar[ul]_{\pi}
\\ & R \ar[ul]^{f} \ar[ur]_{\mathbb{D}[l+1]} &
}
\end{equation*}
where $\pi$ is the quotient map. Then $(\ker \pi)^{e+1}=0$, so $\ker(\pi)$ is nilpotent. Since the map $R\to S$ is \'{e}tale, we get a unique $k$-algebra map
$$S\to S[\mathbf{X}]/(X_1^{p^{l+1}},\ldots,X_e^{p^{l+1}})$$
completing the diagram above.

Assume that $x_l=c_1x_1+\ldots+c_{l-1}x_{l-1}$ for some $c_1,\ldots, c_{l-1}\in C$. By Lemma \ref{absconst}, each $D_{\mathbf{i}}$ is $C$-linear. Hence we obtain that the rank of our Wronskian matrix is smaller than $l$ as in the standard case (see \cite[Thm. II.1]{kol1}).
\\
Let the rank of the matrix $\big(D_{\mathbf{i}}(x_j)\big)_{\mathbf{i}\in [p]^e,j\leqslant l}$ be equal to $r<l$. After reordering $x_1,\ldots,x_l$, we may assume that the matrix $\big(D_{\mathbf{i}}(x_j)\big)_{\mathbf{i}\in [p]^e,j\leqslant r}$ has rank $r$. Therefore there exist $\lambda_1,\ldots, \lambda_{r+1}\in K$, not all equal to $0$, such that for each tuple $\mathbf{k}$ we have
\begin{equation}
\sum\limits_{s=1}^{r+1}\lambda_sD_{\mathbf{k}}(x_s)=0.\tag{$*$}
\end{equation}
\noindent
Reordering and dividing by $c_{r+1}$ if need be, we may assume that $c_{r+1}=1$. By Remark \ref{gderint2}, there are $c_{\mathbf{i},\mathbf{j}}^{\mathbf{k}}\in C$ such that for all tuples $\mathbf{i},\mathbf{j}$ we have
$$D_{\mathbf{j}}\circ D_{\mathbf{i}}=\sum_{\mathbf{k}}c_{\mathbf{i},\mathbf{j}}^{\mathbf{k}}D_{\mathbf{k}}.$$
Hence for $\mathbf{1}:=(1,0,\ldots,0)$ and every tuple $\mathbf{i}$ we get (using $(*)$ with $\mathbf{k}=\mathbf{1}$ for the last equality)
\begin{IEEEeqnarray*}{rCl}
0 & = & \sum\limits_{s=1}^{r+1}D_{\mathbf{1}}(\lambda_s)D_{\mathbf{i}}(x_s)+\sum\limits_{s=1}^{r+1}\lambda_sD_{\mathbf{1}}(D_{\mathbf{i}}(x_s))  \\
 & = & \sum\limits_{s=1}^{r}D_{\mathbf{1}}(\lambda_s)D_{\mathbf{i}}(x_s)+\sum\limits_{\mathbf{l}}c_{\mathbf{1},\mathbf{i}}^{\mathbf{l}}\sum\limits_{s=1}^{r+1}\lambda_sD_{\mathbf{l}}(x_s) \\
 & = & \sum\limits_{s=1}^{r}D_{\mathbf{1}}(\lambda_s)D_{\mathbf{i}}(x_s).
\end{IEEEeqnarray*}
Thus $D_{(1,0,\ldots,0)}(\lambda_s)=0$ for every $s\leqslant r$. After similar reasoning for the derivations $D_{(0,1,0,\ldots,0)},\ldots,D_{(0,\ldots,0,1)}$ we get $\lambda_1,\ldots,\lambda_{r+1}\in C$. By setting $\mathbf{k}=\mathbf{0}$ in $(*)$, we obtain that $x_1,\ldots,x_l$ are linearly dependent over $C$.

We introduce the following notation:
$$\partial^F_1=D_{(1,0,\ldots,0)},\ldots,\partial^F_e=D_{(0,\ldots,0,1)}.$$
Let $i\leqslant e$ and $f\in K$. By the chain rule, we get
\begin{equation}
\partial^F_i(f)=\Big(\frac{\partial F_i}{\partial Y_j}(\mathbf{X},0)\Big)_{i,j}\cdot \Big(\frac{\partial f}{\partial X_1},\ldots,\frac{\partial f}{\partial X_e}\Big).\tag{$*$}
\end{equation}
Let $J$ denote the Jacobian matrix appearing in $(*)$. Then $J$ is the matrix of the derivative (at $\mathbf{0}$) of the formal map which is the ``$F$-multiplication by $\mathbf{X}$''. Since this formal map is (formally) invertible, the matrix $J$ is non-singular. Therefore $f$ belongs to the field of constants if and only if $\frac{\partial f}{\partial X_i}=0$ for each $i$. The latter condition occurs if and only if $f$ is a $p$-th power, so the result is proved.

By Remark \ref{defgen}(1), Proposition \ref{etalegext} and Lemma \ref{lamb}(3), we can assume that $K$ is a field. By Lemma \ref{lamb}(1), we have $K^p=L^p\cap K$. Since $\mathbf{L}\models \mathfrak{g}-\dcf_{\lambda}$, $\mathbf{L}$ is strict and hence $\mathbf{K}$ is strict as well.
By Proposition \ref{lambdaap} and Lemma \ref{lamb}(2), we can $L^{\lambda}_{e,m}$-amalgamate $\mathbf{F}$ and $\mathbf{L}$ over $\mathbf{K}$ into a strict $\mathfrak{g}$-field $\mathbf{F}'$. Since the extension $L\subseteq F'$ is separable, by \cite[Claim 2.2]{Del1} there is an elementary extension in the language of fields $L\preccurlyeq L'$ and a field embedding $\Upsilon:F'\to L'$ over $L$. The situation is described in the following diagram:
\begin{equation*}
\xymatrixcolsep{4pc}
\xymatrix{  &   &  L'\\
 &  \mathbf{F}'\ar[ru]^{\Upsilon} &  \\
\mathbf{F}\ar[ru]^{} &   & \mathbf{L}\ar[lu]^{} \ar[uu]^{\preccurlyeq}\\
  &  \mathbf{K}\ar[ru]^{}\ar[lu]^{}.  &  }
\end{equation*}
By Lemma \ref{elementaryetale}, the extension $L\subseteq L'$ is \'{e}tale. The $\mathfrak{g}$-field $\mathbf{F}'$ is strict, so by Corollary \ref{dimconstants}, we have $[F':(F')^p]\leqslant p^e$. Since the extension $L\subseteq F'$ is separable and $[L:L^p]=p^e$, by the equivalence between $(1)$ and $(2)$ in Lemma \ref{elementaryetale}, the extension $L\subseteq F'$ is \'{e}tale. Then the extension $F'\subseteq L'$ is  \'{e}tale as well. By Proposition \ref{etalegext}, there is a $\mathfrak{g}$-derivation on $L'$ extending the one on $F'$ (hence also extending the one on $L$). By Lemma \ref{elementaryetale}, the extension $\mathbf{L}\subseteq \mathbf{L}'$ is $L^{\lambda}_{e,m}$-elementary and we are done.

Let $f\in Xk\llbracket X\rrbracket$ be an isomorphism between $F_1$ and $F_2$. For any $F_1$-derivation $\mathbb{D}:K\to K\llbracket X\rrbracket$, the following composition
\begin{equation*}
\xymatrix{K \ar[r]^{\mathbb{D}}  & K\llbracket X\rrbracket \ar[r]^{\ev_f}  & K\llbracket X\rrbracket}
\end{equation*}
is an $F_2$-derivation. It is easy to see that for each positive integer $n$, there are $c_{n,1},\ldots,c_{n,n}\in k$ such that if $\mathbb{D}=(D_i)_{i\in {\mathds{N}}}$ then the corresponding $F_2$-derivation $\ev_f\circ \mathbb{D}$ is of the form
$$(\id,c_{1,1}D_1,c_{2,1}D_1+c_{2,2}D_2,\ldots),$$
hence the result follows.

remark.raw:
\label{defgen}
Proposition \ref{etalehs} enables us to generalize Definition \ref{hstrdef} in the following way.
\begin{enumerate}
\item Since the localization maps are \'{e}tale (see \cite[p. 193]{mat}), any ($m$-truncated) $e$-dimensional HS-derivation on $R$ uniquely extends to an ($m$-truncated) $e$-dimensional HS-derivation on a localization of $R$.

\item By $(1)$, we get a notion of an ($m$-truncated) $e$-dimensional HS-derivation on any scheme over $k$.

\item Proposition \ref{etalehs} generalizes to schemes over $k$.

\item The notion of an ($m$-truncated) $e$-dimensional HS-derivation on a scheme $V$ is a special case of the notion of a \emph{$\underline{\mathcal{D}}$-structure} on a scheme $V$, see \cite{MS}. We will discuss possible generalizations of the results of this paper to the context of \cite{MS} in Section \ref{msecop}.

\item It is easy to generalize the assumptions of Proposition \ref{etalehs} to include the case of ($m$-truncated) $e$-dimensional HS-derivations \emph{from $R$ to $S$}.
\end{enumerate}

\label{gderint}
A $\mathfrak{g}$-derivation on $R$ is the same as an $m$-truncated $e$-dimensional
HS-derivation on $R$ over $k$ satisfying a ``$\mathfrak{g}$-iterativity'' rule. It is easy to see that the trivial action of the unit morphism corresponds
to the condition $D_{\mathbf{0}}=\id_R$ and the diagram expressing the mixed associativity of the $k$-group scheme action $d$ is the following ``$\mathfrak{g}$-iterativity'' diagram
\begin{equation*}
\xymatrix{R \ar[r]^d \ar[d]_d & R[\mathbf{v}_m] \ar[d]^{d[\mathbf{v}_m]}
 \\ R[\mathbf{w}_m]\ar[r]^{c} & R[\mathbf{w}_m,\mathbf{v}_m]}
\end{equation*}
where $\mathbf{w}_m$ is another ``$m$-truncated $e$-tuple of variables'' and $c$ is the Hopf algebra comultiplication given by $\mathfrak{g}$. Therefore for an arbitrary $k$-scheme $V$, any $\mathfrak{g}$-derivation on $V$ is also an $m$-truncated $e$-dimensional HS-derivation on $V$ over $k$ in the sense of Remark \ref{defgen}(2).

\label{gderint2}
We will give another interpretation of the $\mathfrak{g}$-iterativity condition. Suppose that the matrix (in the standard basis) of the $k$-linear comultiplication map $c$ from Remark \ref{gderint} has the form $(c_{\mathbf{i},\mathbf{j}}^{\mathbf{k}})$. Suppose also that $\mathbb{D}=(D_{\mathbf{i}})_{\mathbf{i}}$ is an $m$-truncated $e$-dimensional HS-derivation on $R$ over $k$. Then $\mathbb{D}$ is a $\mathfrak{g}$-derivation if and only if for all $\mathbf{i},\mathbf{j}$ we have
$$D_{\mathbf{j}}\circ D_{\mathbf{i}}=\sum_{\mathbf{k}}c_{\mathbf{i},\mathbf{j}}^{\mathbf{k}}D_{\mathbf{k}}.$$

\begin{enumerate}
\item As in Remarks \ref{gderint}, \ref{gderint2}, any $F$-derivation is an $e$-dimensional HS-derivation which satisfies the \emph{$F$-iterativity law}.



\item Note that a $G$-derivation on $V$ (i.e. a direct system of group scheme actions of $G[m]$ on $V$) is \emph{not} the same as an algebraic action of $G$ on $V$. Clearly, any algebraic action of $G$ on $V$ gives a $G$-derivation by restricting the action of $G$ to $G[m]$ for each $m$. The difference between these two notions is easy to observe for $R=k[t]$ and $G=\mathbb{G}_{\rm{a}}$. If $\mathbb{D}$ is a $\mathbb{G}_{\rm{a}}$-derivation on $R$ (i.e. an iterative HS-derivation on $R$), then $\mathbb{D}$ comes from a $\mathbb{G}_{\rm{a}}$-action on $\spec(R)$ if and only if there is $n$ such that for all $i>n$, we have $D_i(t)=0$.

\end{enumerate}

\label{factorstrict}
Let $V^{\fr^m}$ be $V$ twisted by the $m$-th power of the Frobenius automorphism as in Section \ref{gpschemetrun}. From the universal property of quotients, there is a unique morphism $\Psi$ making the following diagram commutative
\begin{equation*}
\xymatrixcolsep{4pc}
\xymatrix{V \ar[d]_{\fr^m_V} \ar[r]^{}& V/\mathfrak{g} \ar[dl]_{\Psi}\\
	   V^{\fr^m} .  }
\end{equation*}
If $V=\spec(R)$ and $m=1$, then $\mathbf{R}$ is strict if and only if $\Psi$ is an isomorphism. It is also easy to see that for a reduced $R$ and arbitrary $m$,  $\mathbf{R}$ is strict if and only if $\Psi$ is an isomorphism.

\label{values}
\begin{enumerate}
\item The proof above may seem to be technical, but the idea is very simple. For $\mathbf{j}\in [p^{m-1}]^{\times e}$, the value $D_{\mathbf{j}}(a^{1/p})$ is determined by Claim 1. For $i\leqslant e$, we set $D_{(p^{m-1})_i}(a^{1/p})$ as a new formal variable. The values of the remaining operators on $a^{1/p}$ are determined by the $\mathfrak{g}$-iterativity rule.

\item 

\item The above proof may be also used to show that a $\mathfrak{g}$-field is strict if and only if it is \emph{differentially perfect}, i.e. each of its differential extension is separable. This generalizes a result of Kolchin (see Chapter II, Section 3., Proposition 5.(a) in \cite{kol1}).
\end{enumerate}

\begin{enumerate}
\item The extra property which makes the theory $F-\ddf$ nicer than the theory $\mathfrak{g}-\ddf$ is the existence of the \emph{smallest} strict extensions (Proposition \ref{strictext}). It gives the amalgamation property for \emph{all} (i.e. not necessarily strict) $F$-fields (Proposition \ref{apf}) and the quantifier elimination for $F-\dcf$.

\item In this context, quantifier elimination for $F-\dcf$ implies elimination of imaginaries for $F-\dcf$ exactly as in Section 4 of \cite{Zieg2}.
\end{enumerate}

