\subsection{Group scheme actions}



We introduce a notion which generalizes the notion of an $m$-truncated iterative HS-derivation from \cite{K3}.
\begin{definition}
\begin{enumerate}
\item A \emph{$\mathfrak{g}$-derivation on $V$} is a $k$-group scheme action of $\mathfrak{g}$ on $V$ (see Section 12 in \cite{MuAbel}).

\item A \emph{$\mathfrak{g}$-derivation on $R$} is a $\mathfrak{g}$-derivation on $\spec(R)$.

\item An \emph{$F$-derivation} on $V$ is a direct system of $F[m]$-derivations on $V$.

\item A \emph{$G$-derivation} is a $\widehat{G}$-derivation (see Section \ref{gpschemetrun} for the definition of $\widehat{G}$).

\item Similarly we get the notions of an $F$-derivation and a $G$-derivation on $R$.
\end{enumerate}
\end{definition}
\begin{remark}
\begin{enumerate}
\item As in Remarks \ref{gderint}, \ref{gderint2}, any $F$-derivation is an $e$-dimensional HS-derivation which satisfies the \emph{$F$-iterativity law}.



\item Note that a $G$-derivation on $V$ (i.e. a direct system of group scheme actions of $G[m]$ on $V$) is \emph{not} the same as an algebraic action of $G$ on $V$. Clearly, any algebraic action of $G$ on $V$ gives a $G$-derivation by restricting the action of $G$ to $G[m]$ for each $m$. The difference between these two notions is easy to observe for $R=k[t]$ and $G=\mathbb{G}_{\rm{a}}$. If $\mathbb{D}$ is a $\mathbb{G}_{\rm{a}}$-derivation on $R$ (i.e. an iterative HS-derivation on $R$), then $\mathbb{D}$ comes from a $\mathbb{G}_{\rm{a}}$-action on $\spec(R)$ if and only if there is $n$ such that for all $i>n$, we have $D_i(t)=0$.

\end{enumerate}
\end{remark}








